'use strict';
/*
 * NewsGPT reader. Renders a frozen edition from window.NEWSGPT_EDITIONS
 * (generated by build.js). No fetch(), so this works over file://.
 */

(function () {
  // Support both modes:
  // 1. Legacy: window.NEWSGPT_EDITIONS (from web/editions.js) — multi-edition picker
  // 2. Offline: window.EDITION (embedded in index.html) — single edition
  var EDITIONS = [];
  if (window.EDITION) {
    // Offline mode: single embedded edition
    EDITIONS = [window.EDITION];
  } else if (Array.isArray(window.NEWSGPT_EDITIONS)) {
    // Legacy mode: multiple editions from bundle
    EDITIONS = window.NEWSGPT_EDITIONS;
  }

  var BRIEF_MAX_IMPORTANCE = 2;

  var el = {
    metaLeft:  document.getElementById('meta-left'),
    metaRight: document.getElementById('meta-right'),
    dateline:  document.getElementById('dateline'),
    summary:   document.getElementById('summary'),
    picker:    document.getElementById('edition-picker'),
    banner:    document.getElementById('banner'),
    lead:      document.getElementById('lead'),
    columns:   document.getElementById('columns'),
    colophon:  document.getElementById('colophon-meta'),
  };

  // --- Escaping -----------------------------------------------------------
  // Story text is scraped from the open web and passed through an LLM. Treat
  // every field as hostile: escape first, then re-introduce only the few
  // inline marks the contract allows.

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  // Only http(s) links are ever emitted as hrefs — blocks javascript: and data:.
  function safeUrl(url) {
    return /^https?:\/\//i.test(String(url || '')) ? String(url) : null;
  }

  /* Markdown-lite: paragraphs, **bold**, *italic*. Nothing else, by design —
     the contract promises nothing else, and a full parser is attack surface. */
  function renderBody(md) {
    if (!md) return '';
    return String(md)
      .split(/\n{2,}/)
      .map(function (para) {
        var html = esc(para.trim()).replace(/\n/g, ' ');
        if (!html) return '';
        html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
        html = html.replace(/(^|[\s(])\*([^*\n]+)\*(?=[\s).,;:!?]|$)/g, '$1<em>$2</em>');
        return '<p>' + html + '</p>';
      })
      .join('');
  }

  // --- Formatting ---------------------------------------------------------

  function longDate(ymd) {
    var parts = String(ymd).split('-');
    var d = new Date(Date.UTC(+parts[0], +parts[1] - 1, +parts[2]));
    if (isNaN(d.getTime())) return String(ymd);
    return d.toLocaleDateString('en-US', {
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC',
    });
  }

  function sentimentTag(value) {
    if (value === null || value === undefined) return '';
    var cls = 'flat', mark = '◆', word = 'Mixed';
    if (value >= 0.15)       { cls = 'up';   mark = '▲'; word = 'Positive'; }
    else if (value <= -0.15) { cls = 'down'; mark = '▼'; word = 'Negative'; }
    return '<span class="sentiment sentiment--' + cls + '">' +
             mark + ' ' + word + ' ' + (value > 0 ? '+' : '') + value.toFixed(2) +
           '</span>';
  }

  function kindLabel(kind) {
    if (kind === 'ticker') return 'Ticker';
    if (kind === 'macro') return 'Macro';
    return 'Sector';
  }

  function footnotes(sources) {
    var items = (sources || []).map(function (src, i) {
      var url = safeUrl(src.url);
      var label = esc(src.publisher || src.title || 'Source');
      var title = esc([src.title, src.publisher, src.published_at].filter(Boolean).join(' — '));
      if (!url) return '<span class="footnote"><sup>' + (i + 1) + '</sup>' + label + '</span>';
      return '<a class="footnote" href="' + esc(url) + '" title="' + title + '"' +
             ' target="_blank" rel="noopener noreferrer nofollow">' +
             '<sup>' + (i + 1) + '</sup>' + label + '</a>';
    });
    return items.length ? '<span class="footnotes">' + items.join('') + '</span>' : '';
  }

  function storyMeta(story) {
    var bits = [];
    if (story.tickers && story.tickers.length) {
      bits.push('<span class="story-tickers">' + esc(story.tickers.join(' · ')) + '</span>');
    }
    if (story.merged_count > 1) {
      bits.push('<span class="merged">' + story.merged_count + ' reports</span>');
    }
    var notes = footnotes(story.sources);
    if (notes) bits.push(notes);
    return bits.length ? '<div class="story-meta">' + bits.join('') + '</div>' : '';
  }

  // --- Story rendering ----------------------------------------------------

  function renderStory(story, isMajor) {
    return '<article class="story' + (isMajor ? ' story--major' : '') + '">' +
             '<h3 class="story-headline">' + esc(story.headline) + '</h3>' +
             (story.dek ? '<p class="story-dek">' + esc(story.dek) + '</p>' : '') +
             (story.body_md ? '<div class="story-body">' + renderBody(story.body_md) + '</div>' : '') +
             storyMeta(story) +
           '</article>';
  }

  function renderBrief(story) {
    return '<article class="brief">' +
             '<span class="brief-headline">' + esc(story.headline) + '</span>' +
             storyMeta(story) +
           '</article>';
  }

  function renderColumn(section, leadId) {
    var stories = (section.stories || []).filter(function (s) { return s.id !== leadId; });
    if (!stories.length) return '';

    var full = stories.filter(function (s) { return s.importance > BRIEF_MAX_IMPORTANCE; });
    var briefs = stories.filter(function (s) { return s.importance <= BRIEF_MAX_IMPORTANCE; });

    var html = '<section class="column column--' + esc(section.kind) + '">' +
      '<header class="column-head">' +
        '<div class="column-kicker">' +
          '<span>' + esc(kindLabel(section.kind)) + '</span>' +
          sentimentTag(section.sentiment) +
          '<span class="count">' + stories.length + '</span>' +
        '</div>' +
        '<h2 class="column-title">' + esc(section.title) + '</h2>' +
        (section.kind !== 'ticker' && section.tickers && section.tickers.length
          ? '<div class="tickers">' + esc(section.tickers.join(' · ')) + '</div>' : '') +
      '</header>' +
      (section.lede ? '<p class="column-lede">' + esc(section.lede) + '</p>' : '');

    html += full.map(function (s, i) { return renderStory(s, i === 0); }).join('');

    if (briefs.length) {
      html += '<div class="briefs">' +
                '<h3 class="briefs-head">In Brief</h3>' +
                briefs.map(renderBrief).join('') +
              '</div>';
    }

    return html + '</section>';
  }

  function renderLead(story) {
    if (!story) { el.lead.hidden = true; return; }
    el.lead.hidden = false;
    el.lead.innerHTML =
      '<p class="lead-kicker">' +
        esc((story.tickers && story.tickers.length ? story.tickers.join(' · ') + ' — ' : '') +
            (story.sector || 'Markets')) +
      '</p>' +
      '<h2 class="lead-headline">' + esc(story.headline) + '</h2>' +
      (story.dek ? '<p class="lead-dek">' + esc(story.dek) + '</p>' : '') +
      (story.body_md ? '<div class="lead-body">' + renderBody(story.body_md) + '</div>' : '') +
      storyMeta(story);
  }

  // --- Edition rendering --------------------------------------------------

  function findStory(edition, id) {
    if (!id) return null;
    for (var i = 0; i < edition.sections.length; i++) {
      var found = edition.sections[i].stories.filter(function (s) { return s.id === id; })[0];
      if (found) return found;
    }
    return null;
  }

  function render(edition) {
    // Editions are newest-first; number them from the oldest so No. rises over time.
    var issueNo = EDITIONS.length - EDITIONS.indexOf(edition);

    document.title = 'NewsGPT — ' + edition.edition_date;
    el.dateline.textContent = longDate(edition.edition_date);

    var columnCount = edition.sections.length;
    el.summary.textContent = edition.story_count + ' stories across ' + columnCount +
      ' column' + (columnCount === 1 ? '' : 's');

    el.metaLeft.innerHTML = 'Vol. I &middot; No. ' + issueNo + '<br>AI-generated edition';
    el.metaRight.innerHTML = 'Compiled by Hermes<br>' +
      esc((edition.run_ids || []).length + ' scrape run' +
          ((edition.run_ids || []).length === 1 ? '' : 's'));

    if (edition.sample) {
      el.banner.hidden = false;
      el.banner.textContent =
        'Sample edition — synthetic placeholder data, not real news. ' +
        'Clear data/inbox/ once Hermes is writing real chunks.';
    } else {
      el.banner.hidden = true;
    }

    var lead = findStory(edition, edition.lead_story_id);
    renderLead(lead);

    var html = edition.sections
      .map(function (s) { return renderColumn(s, edition.lead_story_id); })
      .join('');

    el.columns.innerHTML = html ||
      '<p class="empty">This edition has no stories outside the lead.</p>';

    var generated = new Date(edition.generated_at);
    el.colophon.textContent = 'Edition ' + edition.edition_date +
      ' · built ' + (isNaN(generated.getTime()) ? edition.generated_at : generated.toLocaleString()) +
      (edition.run_ids && edition.run_ids.length
        ? ' · runs: ' + edition.run_ids.join(', ') : '');

    window.scrollTo(0, 0);
  }

  // --- Boot ---------------------------------------------------------------

  if (!EDITIONS.length) {
    el.dateline.textContent = 'No editions';
    el.summary.textContent = 'run node build.js';
    el.columns.innerHTML = '<p class="empty">Nothing to read yet. Put a Hermes drop in ' +
      '<code>data/raw/</code> and run <code>node build.js</code>.</p>';
    if (el.picker) el.picker.hidden = true;
    return;
  }

  // In offline mode (single embedded edition), hide the picker.
  // In legacy mode (multiple editions), show it.
  if (EDITIONS.length === 1 && window.EDITION) {
    if (el.picker) el.picker.hidden = true;
  } else if (el.picker) {
    el.picker.hidden = false;
    el.picker.innerHTML = EDITIONS.map(function (ed, i) {
      return '<option value="' + i + '">' + esc(ed.edition_date) + '</option>';
    }).join('');

    el.picker.addEventListener('change', function () {
      render(EDITIONS[+el.picker.value] || EDITIONS[0]);
    });
  }

  render(EDITIONS[0]);
})();
